mapper.select:
select
    tvr.*,
    concat('合格', ifnull(tvr.qualified_count, 0), '次，不合格', ifnull(tvr.unqualified_count, 0), '次') as evaluation_type_name
from tb_vendor_report tvr



        AND ( tvr.party_a_org_id = #{scopeId} OR tvr.party_a_org_id in (
            select t.thrid_dept_id from sys_dept t where FIND_IN_SET(
                (select dept_id from sys_dept where thrid_dept_id = #{scopeId}),
                t.ancestors)
            )
        )


        AND tvr.enterprise_location like concat('%',#{area},'%')


        AND tvr.party_a_org_id = #{deptId}


        AND tvr.apply_time >= #{startDate}


        AND tvr.apply_time <= #{endDate}


        AND tvr.expenditure_business_type = #{expenditureBusinessType}


        and ( tvr.party_a_org_id = #{id} OR tvr.party_a_org_id in (
            select t.thrid_dept_id from sys_dept t where FIND_IN_SET(
                (select dept_id from sys_dept where thrid_dept_id = #{id}),
                t.ancestors)
            )
        )


        AND tvr.min_account_code = #{minAccountCode}


order by ifnull(tvr.qualified_count, 0) desc
